mapper.select:
SELECT PAYHSRCSECINFO.SECID, PAYHSRCSECINFO.SECNAME, PAYHSRCSECINFO.SECFULLNAME, PAYHSRCSECINFO.SECCODE, PAYHSRCSECINFO.MARKET, PAYHSRCSECINFO.INSTITUTION, PAYHSRCSECINFO.ISSUEPRICE, PAYHSRCSECINFO.PUBENDDATE, PAYHSRCSECINFO.VDATE, PAYHSRCSECINFO.MDATE, PAYHSRCSECINFO.ISSUEAMT, CUSTOMER_INFO1.CUSTOMER_NAME issuerName, PAYHSRCSECINFO.SECTYPE, PAYHSRCSECINFO.SECTYPE2, CASE PAYHSRCSECINFO.ISSUETYPE WHEN '01' THEN '1' ELSE '2' END AS ISSUETYPE, PAYHSRCSECINFO.BLNAREA, PAYHSRCSECINFO.ISSUS, PAYHSRCSECINFO.ISSECBOND, PAYHSRCSECINFO.CITY_INVEST_SEC_CHB CITYINVESTSECWIND, PAYHSRCSECINFO.CCY, PAYHSRCSECINFO.FACEVALUE, CUSTOMER_INFO2.CUSTOMER_NAME WARRANTOR, PAYHSRCSECINFO.GUARTYPE, CASE
WHEN ( PAYHSRCSECINFO.CALLOPTION = 'Y' OR PAYHSRCSECINFO.PUTOPTION = 'Y' ) THEN 'Y' ELSE 'N' END AS IS_RIGHT, PAYHSRCSECINFO.REMARK, PAYHSRCSECINFO.COUPONSPECIES, PAYHSRCSECINFO.INTERESTRATE, PAYHSRCSECINFO.PAPERIR, PAYHSRCSECINFO.SPREADRATE_8 SPREADRATE8, PAYHSRCSECINFO.RATECODE, PAYHSRCSECINFO.COEFFICIENT, PAYHSRCSECINFO.TOPRATE, PAYHSRCSECINFO.BOTTOMRATE, PAYHSRCSECINFO.RESETTYPE, PAYHSRCSECINFO.OBSERVEBEFDAY, PAYHSRCSECINFO.OBSERVEBEFUNIT, CASE
WHEN ( PAYHSRCSECINFO.RATEBASIC = 'A/A_B_COUP' OR PAYHSRCSECINFO.PUTOPTION = 'A_B_DAY' ) THEN 'A/A' ELSE PAYHSRCSECINFO.RATEBASIC END AS RATEBASIC, CASE
WHEN PAYHSRCSECINFO.RATEBASIC = 'A/A_B_COUP' THEN '02' WHEN PAYHSRCSECINFO.RATEBASIC = 'A/A_B_DAY' THEN '01' END AS BASISSTYLE, PAYHSRCSECINFO.WORKDAYRULE, PAYHSRCSECINFO.PAYCYCLE, PAYHSRCSECINFO.SCHECALRULE, PAYHSRCSECINFO.FIRSTRATEDAY, PAYHSRCSECOPTION.OPTIONTYPE, PAYHSRCSECOPTION.THEORYOPTIONPAYDAY, PAYHSRCSECRATING.RATING ztGradeResult, PAYHSRCSECRATING.RATINGORG ztGradeOrgId, PAYHSRCSECRATING2.RATING zxGradeResult, PAYHSRCSECRATING2.RATINGORG zxGradeOrgId FROM
INTERF_PAYHSRCSECINFO PAYHSRCSECINFO
LEFT JOIN INTERF_CUSTOMER_INFO CUSTOMER_INFO1 ON PAYHSRCSECINFO.ISSUERSHORT = CUSTOMER_INFO1.CUSTOMER_ID LEFT JOIN INTERF_CUSTOMER_INFO CUSTOMER_INFO2 ON CUSTOMER_INFO1.CUSTOMER_ID = PAYHSRCSECINFO.GUARANTOR
LEFT JOIN ( SELECT SECID, OPTIONTYPE, THEORYOPTIONPAYDAY FROM ( SELECT ROW_NUMBER ( ) OVER ( PARTITION BY PAYHSRCSECOPTION.SECID ORDER BY PAYHSRCSECOPTION.THEORYOPTIONPAYDAY DESC ) NUM, SECID, OPTIONTYPE, THEORYOPTIONPAYDAY FROM INTERF_PAYHSRCSECOPTION PAYHSRCSECOPTION WHERE PAYHSRCSECOPTION.THEORYOPTIONPAYDAY > to_date( #{platformDate}, 'YYYY-MM-DD' ) ) WHERE NUM = 1 ) PAYHSRCSECOPTION ON PAYHSRCSECOPTION.SECID = PAYHSRCSECINFO.SECID
LEFT JOIN (SELECT SECID,RATING,RATINGORG,row_number () over (partition BY SECID ORDER BY RATING ASC) num FROM INTERF_PAYHSRCSECRATING WHERE ratingtype='C') PAYHSRCSECRATING ON PAYHSRCSECRATING.SECID = PAYHSRCSECINFO.SECID AND PAYHSRCSECRATING.NUM = 1 LEFT JOIN (SELECT SECID,RATING,RATINGORG,row_number () over (partition BY SECID ORDER BY RATING ASC) num FROM INTERF_PAYHSRCSECRATING WHERE ratingtype='I') PAYHSRCSECRATING2 ON PAYHSRCSECRATING2.SECID = PAYHSRCSECINFO.SECID AND PAYHSRCSECRATING2.NUM = 1
PAYHSRCSECINFO.VDATE <= to_date ( #{platformDate}, 'YYYY-MM-DD' )
AND PAYHSRCSECINFO.SECID = #{secId,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.MARKET = #{market,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.institution = #{institution,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUERSHORT = #{issuer,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.PUBENDDATE >= #{issueDateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.PUBENDDATE <= #{issueDateEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.VDATE >= #{vdateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.VDATE <= #{vdateEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.MDATE >= #{mdateStart,jdbcType=DATE}
AND PAYHSRCSECINFO.MDATE <= #{mdateEnd,jdbcType=DATE}
AND PAYHSRCSECOPTION.THEORYOPTIONPAYDAY >= #{theOryOptionPayDayStart,jdbcType=DATE}
AND PAYHSRCSECOPTION.THEORYOPTIONPAYDAY <= #{theOryOptionPayDayEnd,jdbcType=DATE}
AND PAYHSRCSECINFO.COUPONSPECIES = #{couponSpecies,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.INTERESTRATE = #{interestRate,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.PAYCYCLE = #{payCycle,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.CCY = #{ccy,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUS = #{isSus,jdbcType=VARCHAR}
AND PAYHSRCSECINFO.ISSUS = #{isSus,jdbcType=VARCHAR}
AND ( PAYHSRCSECINFO.CALLOPTION = 'Y' OR PAYHSRCSECINFO.PUTOPTION = 'Y')
AND ( PAYHSRCSECINFO.CALLOPTION = 'N' AND PAYHSRCSECINFO.PUTOPTION = 'N')
AND PAYHSRCSECOPTION.OPTIONTYPE = #{optionType,jdbcType=VARCHAR}
AND PAYHSRCSECRATING2.RATING in (#{zxGrade,jdbcType=VARCHAR})
AND PAYHSRCSECRATING.RATING in (#{ztGrade,jdbcType=VARCHAR})
AND ( PAYHSRCSECINFO.SECID like '%' || #{search} || '%' OR PAYHSRCSECINFO.MARKET like '%' || #{search} || '%' OR PAYHSRCSECINFO.institution like '%' || #{search} || '%' OR PAYHSRCSECINFO.ISSUERSHORT like '%' || #{search} || '%' OR to_char(PAYHSRCSECINFO.PUBENDDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECINFO.VDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECINFO.MDATE,'yyyy-MM-dd') = #{search} OR to_char(PAYHSRCSECOPTION.THEORYOPTIONPAYDAY,'yyyy-MM-dd') = #{search} OR PAYHSRCSECINFO.COUPONSPECIES like '%' || #{search} || '%' OR PAYHSRCSECINFO.INTERESTRATE like '%' || #{search} || '%' OR PAYHSRCSECINFO.PAYCYCLE like '%' || #{search} || '%' OR PAYHSRCSECINFO.CCY like '%' || #{search} || '%' OR PAYHSRCSECINFO.ISSUS like '%' || #{search} || '%' OR PAYHSRCSECOPTION.OPTIONTYPE like '%' || #{search} || '%' OR PAYHSRCSECRATING2.RATING like '%' || #{search} || '%' OR PAYHSRCSECRATING.RATING like '%' || #{search} || '%' )
ORDER BY PAYHSRCSECINFO.SECTYPE, PAYHSRCSECINFO.SECTYPE2, PAYHSRCSECINFO.VDATE, PAYHSRCSECINFO.SECID

select SECID, SCHEDUTYPE, TOTALINTERESTSTARTDAY, TOTALINTERESTENDDAY, INTERESTSTARTDAY, INTERESTENDDAY, INTERESTPAYDAY, COUPONRATE, ACCRUEINTAMT, DAILYACCRUEINT, PRINAMTPAY, CASHPAY, PRINAMT, SOURCE from INTERF_PAYHSRCSECSCHEDULE where SECID = #{secid,jdbcType=VARCHAR}
AND INTERESTSTARTDAY >= #{maxTradeDate,jdbcType=VARCHAR}
ORDER BY INTERESTPAYDAY ASC
